+            && Objects.equals(indexFilter, that.indexFilter) && Objects.equals(runtimeFields, that.runtimeFields);
+    }
+
+    @Override
+    public int hashCode() {
+        int result = Objects.hash(originalIndices, indexFilter, nowInMillis, runtimeFields);
