+
+        public ResultsDiff(StreamInput in) throws IOException {
+            this.resultsDiff = DiffableUtils.readJdkMapDiff(
+                in,
+                DiffableUtils.getStringKeySerializer(),
+                SingleFeatureMigrationResult::new,
+                ResultsDiff::readDiffFrom
