+
+        final Request clearVotingRequest = new Request("DELETE", "/_cluster/voting_config_exclusions");
+        clearVotingRequest.setOptions(clearVotingRequest.getOptions().toBuilder().addHeader("Authorization", OPERATOR_AUTH_HEADER));
