+                        logger.error(
+                            new ParameterizedMessage(
+                                "error occurred while reindexing index [{}] from feature [{}] to destination index [{}]",
+                                oldIndexName,
+                                migrationInfo.getFeatureName(),
+                                newIndexName
+                            ),
+                            e
